// רשימת נושאים — הוסיפי / שני לפי רצונך
const TOPICS = [
  'איך לבחור מאפרת לחתונה — 7 שאלות שחייבים לשאול',
  'לוח זמנים מושלם לבוקר החתונה — שעה אחר שעה',
  '5 דברים שכלות מתחרטות שלא עשו לפני החתונה',
  'ספא לפני החתונה — מה כדאי ומה להימנע',
  'מה לארוז לסוויטת הכלות — רשימה מלאה',
  'הקשר בין אמא ובת ביום החתונה — רגעים שלא חוזרים',
  'איך לנשום ביום החתונה — טכניקות הרגעה שעובדות',
  'ליל לפני החתונה — מה לעשות ומה לא',
  'בחירת שמלת כלה — טיפים מהשטח',
  'כיצד לצלם תמונות מהממות בסוויטת הכלות',
  'ניהול עצבים ביום החתונה — מה באמת עוזר',
  'מה כוללת ארוחת בוקר מושלמת לכלה ולמלוות'
];

// בחירה רנדומלית עם הימנעות מחזרות (על בסיס השבוע)
const weekNumber = Math.floor(Date.now() / (7 * 24 * 60 * 60 * 1000));
const topic = TOPICS[weekNumber % TOPICS.length];

const today = new Date().toISOString().split('T')[0];

return [{ json: { topic, today } }];

