const raw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';

// נסיון לחלץ JSON מהתגובה
let article;
try {
  // נקה backticks אם יש
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```\s*$/, '').trim();
  article = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Gemini did not return valid JSON: ' + raw.substring(0, 200));
}

const topic = $('בחירת נושא שבועי').item.json.topic;
const today = $('בחירת נושא שבועי').item.json.today;

// יצירת slug מהתאריך והנושא
const slugDate = today.replace(/-/g, '');
const slugTopic = topic
  .replace(/[^\u05D0-\u05EAa-zA-Z0-9\s]/g, '')
  .trim()
  .split(' ')
  .slice(0, 4)
  .join('-')
  .toLowerCase()
  .replace(/[\u05D0-\u05EA]/g, c => c.charCodeAt(0).toString(16));

const slug = `hagit-${slugDate}-${slugTopic}`.substring(0, 80);

const postData = {
  slug,
  title: article.title,
  metaTitle: article.metaTitle || article.title,
  metaDescription: article.metaDescription || article.excerpt,
  keywords: article.keywords || ['התארגנות כלה', 'סוויטת כלות'],
  excerpt: article.excerpt,
  readTime: article.readTime || '5 דקות קריאה',
  category: article.category || 'טיפים',
  date: today,
  content: article.content
};

// יצירת payload לגיטהאב
const fileContent = Buffer.from(JSON.stringify(postData, null, 2)).toString('base64');

return [{ json: { postData, slug, fileContent, today } }];
